const preferred = 'smtp2go-api';
const matches = $input.first().json.matches || [];
const current = matches.find(m => m.slug === preferred);
const healthy = m => m.current_health && m.current_health.status === 'up';
if (current && healthy(current)) {
  return [{ json: { decision: 'use_preferred', provider: current.slug, endpoint: current.call.endpoint, checked_at: current.current_health.checked_at } }];
}
const alt = matches.find(m => m.slug !== preferred && healthy(m));
return [{ json: {
  decision: alt ? 'needs_approval' : 'stop',
  preferred_status: current ? current.current_health : 'not_returned',
  suggested_alternative: alt ? { slug: alt.slug, name: alt.name, docs: alt.call.docs_url, reliability_score: alt.trust.reliability_score } : null,
  note: 'Advisory only. Do not switch providers automatically: confirm credentials, sending domain and duplicate-send protection first.'
} }];
